(() => {
'use strict';
const P=window.Portal,films=window.PartnerLearningFilms;if(!P||!films)return;
const e=P.e;let dispose=()=>{};
const labels={grid:['Produktion','Stamnät','Regionnät','Lokalnät','Kund'],balance:['Prognos','Handel','Verkligt uttag','Avräkning'],market:['SE1','SE2','SE3','SE4'],price:['Spotkostnad','Avtalade kostnader','Fast avgift','Total elhandel'],hedge:['Prisrisk','Volymrisk','Profilrisk','Områdesrisk'],individual:['Historik','Förändringar','Egen profil','Löpande säkring'],pool:['Kund A','Kund B','Kund C','Gemensam profil'],direct:['Beslut idag','Januari','Februari','Mars'],stable:['Periodvärden','Samma total','Jämn fördelning'],advice:['Behov','Underlag','Alternativ','Beslut']};
function visual(id,index){
if(P.learningIllustration)return P.learningIllustration(id,index);
const examples={price:[['100 kWh × 50 öre',50],['300 kWh × 150 öre',450]],hedge:[['Säkrat',80],['Faktiskt uttag',125]],individual:[['Vinterkund · vinter',80],['Vinterkund · sommar',20],['Sommarkund · vinter',20],['Sommarkund · sommar',80]],pool:[['Säkrat enligt schablon',80],['Faktiskt uttag',110]],direct:[['Januari',6000],['Februari',3000],['Mars',3000]],stable:[['Januari',4000],['Februari',4000],['Mars',4000]]};
const notes={price:'Spotkostnad: 500 kr / 400 kWh = 125 öre/kWh. Övriga kostnader tillkommer.',hedge:'Illustrativ faktisk säkringsgrad: 80 / 125 = 64 %. Volymer i MWh.',individual:'Fiktiv fördelning av årsenergi i procent. Samma årsvolym, olika profiler.',pool:'Illustration: 80 / 110 ≈ 73 %. Volymer i MWh; inte en avräkningsformel.',direct:'Illustrativa periodvärden i kr. Samma total som Stabil: 12 000 kr.',stable:'Illustrativ jämn kronfördelning av samma 12 000 kr. Inte produktens fastställda prisformel.'};
if(examples[id]){const rows=examples[id],max=Math.max(...rows.map(r=>r[1]));return `<div class="lf-chart" role="img" aria-label="${e(notes[id])}">${rows.map(([name,value])=>`<div class="lf-chart-row"><span>${e(name)}</span><div><i style="width:${value/max*100}%"></i></div><strong>${value.toLocaleString('sv-SE')}</strong></div>`).join('')}</div><small class="lf-caption">${e(notes[id])}</small>`;}
return `<div class="lf-diagram" aria-label="${e(labels[id].join(', '))}">${labels[id].map((name,i)=>`<div class="lf-node" style="--delay:${i*.15}s"><span class="lf-number">${String(i+1).padStart(2,'0')}</span><span class="lf-dot"></span><strong>${e(name)}</strong></div>`).join('')}</div><small class="lf-caption">${id==='grid'?'Produktion och uttag kan anslutas på flera nätnivåer. Flöden kan gå i båda riktningar.':id==='market'?'Sveriges fyra elområden. Begränsad överföring kan ge olika områdespriser.':'Förenklad översikt över samband – se berättelsen för rollfördelning.'}</small>`;
}
function render(m){const scenes=films[m.id];if(!scenes)return '';return `<section class="lf-player" data-lf-module="${m.id}" aria-label="Berättad utbildningsfilm"><div class="lf-top"><span>BERÄTTAD BILDFILM</span><span>${scenes.length} avsnitt · ca ${Math.ceil(scenes.reduce((n,s)=>n+s[2].split(/\s+/).length,0)/125)} min</span></div><div class="lf-stage"></div><div class="lf-subtitle" aria-label="Undertext"></div><div class="lf-controls"><button type="button" class="btn btn-primary" data-lf-play>Starta utbildningsfilmen</button><button type="button" class="btn btn-secondary" data-lf-back>Föregående</button><button type="button" class="btn btn-secondary" data-lf-next>Nästa</button><label>Tempo<select data-lf-speed><option value="0.8">Lugnare</option><option value="1" selected>Normal</option><option value="1.2">Snabbare</option></select></label><label><input type="checkbox" data-lf-sound checked> Berättarröst</label></div><progress class="lf-progress" max="${scenes.length}" value="0" aria-label="Filmens framsteg"></progress><p class="lf-status" role="status">En start driver hela momentet framåt. Svensk webbläsarröst används när den finns. Filmvisning ger inte godkänt prov.</p><button type="button" class="btn btn-secondary" data-lf-exam hidden>Filmen är klar – gå till kunskapsprovet</button></section><details class="lf-transcript"><summary>Fördjupning och kundfrågor · läs eller repetera</summary>${scenes.map(s=>`<section><h3>${e(s[0])}</h3><strong>${e(s[1])}</strong><p>${e(s[2])}</p></section>`).join('')}</details>`;}
function bind(m){dispose();const host=document.querySelector('[data-lf-module]');if(!host||!m)return;const scenes=films[m.id],actor=P.prototypeUsers?.current()?.id,synth=window.speechSynthesis;let index=0,chunk=0,playing=false,timer=null,utterance=null,generation=0,dead=false;
const find=s=>host.querySelector(s),text=find('.lf-subtitle'),status=find('.lf-status'),play=find('[data-lf-play]'),sound=find('[data-lf-sound]'),speed=find('[data-lf-speed]');
const parts=()=>scenes[index][2].match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[scenes[index][2]];
const voice=()=>synth?.getVoices().find(v=>/^sv(?:-|_)/i.test(v.lang));
function cancel(){generation++;clearTimeout(timer);timer=null;if(utterance&&synth){utterance.onend=null;utterance.onerror=null;synth.cancel();}utterance=null;}
function paint(){find('.lf-stage').innerHTML=`<span class="lf-kicker">${e(m.title)} · ${index+1}/${scenes.length}</span><h2>${e(scenes[index][0])}</h2>${visual(m.id,index)}<p class="lf-takeaway">${e(scenes[index][1])}</p>`;text.textContent=parts()[chunk].trim();find('.lf-progress').value=index;find('[data-lf-back]').disabled=index===0;find('[data-lf-next]').disabled=index===scenes.length-1;find('[data-lf-exam]').hidden=true;}
function stop(){host.classList.remove("lf-playing");playing=false;cancel();play.textContent='Fortsätt filmen';}
function finish(){stop();find('.lf-progress').value=scenes.length;status.textContent='Filmen är slut. Gör kunskapsprovet för att visa förståelse; filmen godkänner inga resultat.';find('[data-lf-exam]').hidden=false;play.textContent='Spela från början';chunk=parts().length;}
function advance(token){if(dead||token!==generation||!playing)return;if(++chunk>=parts().length){chunk=0;if(++index>=scenes.length){index=scenes.length-1;finish();return;}paint();}speak();}
function speak(){cancel();if(!playing||dead)return;const token=generation,phrase=parts()[chunk].trim();text.textContent=phrase;const selectedVoice=voice();if(sound.checked&&selectedVoice&&window.SpeechSynthesisUtterance){utterance=new SpeechSynthesisUtterance(phrase);utterance.lang='sv-SE';utterance.voice=selectedVoice;utterance.rate=Number(speed.value);utterance.onend=()=>advance(token);utterance.onerror=()=>{if(token!==generation||dead)return;status.textContent='Ljudet kunde inte spelas. Filmen fortsätter med tidsatta undertexter.';timer=setTimeout(()=>advance(token),Math.max(3000,phrase.split(/\s+/).length/2.1*1000/Number(speed.value)));};synth.speak(utterance);status.textContent='Svensk syntetisk berättarröst · undertexter visas samtidigt.';}else{status.textContent=sound.checked?'Ingen svensk röst tillgänglig. Filmen fortsätter automatiskt med tidsatta undertexter.':'Ljud av · filmen fortsätter automatiskt med undertexter.';timer=setTimeout(()=>advance(token),Math.max(3000,phrase.split(/\s+/).length/2.1*1000/Number(speed.value)));}}
play.onclick=()=>{if(playing){stop();return;}if(chunk>=parts().length){index=0;chunk=0;paint();}playing=true;host.classList.add('lf-playing');play.textContent='Pausa';speak();};
function move(delta){cancel();index=Math.max(0,Math.min(scenes.length-1,index+delta));chunk=0;paint();if(playing)speak();}
find('[data-lf-back]').onclick=()=>move(-1);find('[data-lf-next]').onclick=()=>move(1);sound.onchange=speed.onchange=()=>{if(playing)speak();};find('[data-lf-exam]').onclick=()=>document.querySelector('.lp-assessment')?.scrollIntoView({block:'start',behavior:'smooth'});
const visibility=()=>{if(document.hidden&&playing){stop();status.textContent='Pausad när fliken doldes. Fortsätt när du är tillbaka.';}};document.addEventListener('visibilitychange',visibility);
const observer=new MutationObserver(()=>{if(!host.isConnected||P.prototypeUsers?.current()?.id!==actor)cleanup();});observer.observe(document.body,{childList:true,subtree:true});
function cleanup(){if(dead)return;dead=true;stop();observer.disconnect();document.removeEventListener('visibilitychange',visibility);}dispose=cleanup;paint();
}
P.learningFilms={render,bind,stop:()=>dispose(),data:films};
})();
